#!/usr/bin/env node
'use strict';

/**
 * Inlines every module into one executable file. Possible only because the
 * project has no dependencies: a single file can be curled, emailed, or pasted
 * into a gist and run with nothing but Node.
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const OUT = path.join(ROOT, 'dist', 'pet');

// Discovered rather than listed: a hardcoded list silently ships a broken
// bundle the moment a new module is added. Definition order is irrelevant
// because every module is registered before the entry point runs.
const MODULES = fs.readdirSync(path.join(ROOT, 'src'))
  .filter((f) => f.endsWith('.js'))
  .map((f) => f.replace(/\.js$/, ''))
  .sort();

const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));

const parts = [
  '#!/usr/bin/env node',
  "'use strict';",
  `// repotchi ${pkg.version} \u2014 single-file build, generated by tools/bundle.js`,
  `// ${pkg.description}`,
  '',
  `const __pkg = ${JSON.stringify({ version: pkg.version, description: pkg.description })};`,
  'const __defs = {};',
  'const __cache = {};',
  'function __require(name) {',
  "  if (name === '../package.json') return __pkg;",
  "  if (!name.startsWith('./')) return require(name);",
  "  const key = name.slice(2);",
  '  if (__cache[key]) return __cache[key].exports;',
  '  const module = { exports: {} };',
  '  __cache[key] = module;',
  '  __defs[key](module, module.exports, __require);',
  '  return module.exports;',
  '}',
  '',
];

for (const name of MODULES) {
  const body = fs.readFileSync(path.join(ROOT, 'src', `${name}.js`), 'utf8');
  parts.push(`__defs[${JSON.stringify(name)}] = function (module, exports, require) {`);
  parts.push(body.replace(/\s+$/, ''));
  parts.push('};', '');
}

parts.push("__require('./cli').main(process.argv.slice(2));", '');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, parts.join('\n'), { mode: 0o755 });

const size = fs.statSync(OUT).size;
process.stdout.write(`wrote ${path.relative(ROOT, OUT)} (${(size / 1024).toFixed(1)} kB, ${MODULES.length} modules inlined)\n`);
